using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;

// Asset authoring only. Do not run as a player initializer or rewrite any scenes/settings.
public static class CatWorldBake {
 const string Root="Assets/CombatPrototype/Resources/CatWorld";
 [MenuItem("万象归途/美术/生成原创猫族资源")]
 public static void Bake(){foreach(var f in new[]{"Meshes","Materials","Actors","Props","Icons","Weapons"})Directory.CreateDirectory(Root+"/"+f);AssetDatabase.Refresh();
  foreach(string name in new[]{"Sphere","Box","Ear","Cylinder","Gem"}){string path=Root+"/Meshes/"+name+".asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)==null)AssetDatabase.CreateAsset(CatWorldArt.Geometry(name),path);}
  foreach(string name in CatWorldArt.Materials){string path=Root+"/Materials/"+name+".mat";if(AssetDatabase.LoadAssetAtPath<Material>(path)==null)AssetDatabase.CreateAsset(CatWorldArt.Mat(name),path);}
  AssetDatabase.SaveAssets();AssetDatabase.Refresh();
  foreach(string name in CatWorldArt.Actors){var g=CatWorldArt.Actor(name);try{PrefabUtility.SaveAsPrefabAsset(g,Root+"/Actors/"+name+".prefab");}finally{UnityEngine.Object.DestroyImmediate(g);}}
  foreach(string key in CatWorldProps.Keys){var g=CatWorldProps.Build(key);try{PrefabUtility.SaveAsPrefabAsset(g,Root+"/Props/"+key+".prefab");if(key=="sword"||key=="spear"||key=="staff"||key=="bow")PrefabUtility.SaveAsPrefabAsset(g,Root+"/Weapons/"+key+".prefab");Icon(g,key);}finally{UnityEngine.Object.DestroyImmediate(g);}}
  AssetDatabase.SaveAssets();AssetDatabase.Refresh();Debug.Log("B10_CAT_ASSETS_BAKED original geometry and transparent icons; existing rig/CC0 clips retained");
 }
 static void Icon(GameObject model,string key){ShaderUtil.allowAsyncCompilation=false;var oldAmbient=RenderSettings.ambientLight;var oldMode=RenderSettings.ambientMode;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.6f,.6f,.6f);model.transform.position=new Vector3(0,-1000,0);var renderers=model.GetComponentsInChildren<Renderer>().Where(r=>r.gameObject.activeInHierarchy).ToArray();var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var c=new GameObject("IconCamera",typeof(Camera));var light=new GameObject("IconLight",typeof(Light));RenderTexture target=null;Texture2D image=null;var owned=new System.Collections.Generic.List<Material>();
  try{foreach(var renderer in renderers){var m=new Material(Shader.Find("WanxiangGuitu/CatIconStudio"));m.SetColor("_BaseColor",renderer.sharedMaterial.GetColor("_BaseColor"));m.SetFloat("_Metallic",renderer.sharedMaterial.GetFloat("_Metallic"));owned.Add(m);renderer.sharedMaterial=m;}var cam=c.GetComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.clear;cam.orthographic=true;cam.orthographicSize=bounds.extents.magnitude*1.12f;cam.cullingMask=1<<2;cam.nearClipPlane=.01f;cam.farClipPlane=50;cam.transform.position=bounds.center+new Vector3(1,.65f,2.6f).normalized*8;cam.transform.LookAt(bounds.center);var l=light.GetComponent<Light>();l.type=LightType.Directional;l.intensity=1.1f;light.transform.rotation=Quaternion.Euler(35,145,0);target=new RenderTexture(256,256,24,RenderTextureFormat.ARGB32);cam.targetTexture=target;cam.Render();var before=RenderTexture.active;RenderTexture.active=target;try{image=new Texture2D(256,256,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,256,256),0,0);image.Apply();File.WriteAllBytes(Root+"/Icons/"+key+".png",image.EncodeToPNG());}finally{RenderTexture.active=before;}AssetDatabase.ImportAsset(Root+"/Icons/"+key+".png");var importer=(TextureImporter)AssetImporter.GetAtPath(Root+"/Icons/"+key+".png");importer.textureType=TextureImporterType.Default;importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.isReadable=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}
  finally{foreach(var m in owned)UnityEngine.Object.DestroyImmediate(m);RenderSettings.ambientLight=oldAmbient;RenderSettings.ambientMode=oldMode;UnityEngine.Object.DestroyImmediate(c);UnityEngine.Object.DestroyImmediate(light);if(target!=null){target.Release();UnityEngine.Object.DestroyImmediate(target);}if(image!=null)UnityEngine.Object.DestroyImmediate(image);}}
 public static void Batch(){try{Bake();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
